1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	import org.springframework.samples.petclinic.rest.validation.IdentityKeyNormalizer;
12	
13	import java.util.Collection;
14	import java.util.List;
15	import java.util.Map;
16	
17	/**
18	 * Maps Owner & OwnerDto using Mapstruct
19	 */
20	@Mapper(uses = PetMapper.class)
21	public interface OwnerMapper {
22	
23	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
24	    @Mapping(target = "initials", expression = "java(initials(owner))")
25	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
26	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
27	    @Mapping(target = "locality", expression = "java(locality(owner))")
28	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
29	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
30	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
31	    OwnerDto toOwnerDto(Owner owner);
32	
33	    Owner toOwner(OwnerDto ownerDto);
34	
35	    /**
36	     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
37	     */
38	    default String displayName(Owner owner) {
39	        if (owner == null) {
40	            return null;
41	        }
42	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
43	        String firstName = owner.getFirstName() == null ? "" : owner.getFirstName();
44	        return lastName + ", " + firstName;
45	    }
46	
47	    /**
48	     * Returns the upper-cased first letters of firstName and lastName,
49	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
50	     */
51	    default String initials(Owner owner) {
52	        if (owner == null) {
53	            return null;
54	        }
55	        StringBuilder sb = new StringBuilder();
56	        String firstName = owner.getFirstName();
57	        String lastName = owner.getLastName();
58	        if (firstName != null && !firstName.isEmpty()) {
59	            sb.append(Character.toUpperCase(firstName.charAt(0))).append('.');
60	        }
61	        if (lastName != null && !lastName.isEmpty()) {
62	            sb.append(Character.toUpperCase(lastName.charAt(0))).append('.');
63	        }
64	        return sb.toString();
65	    }
66	
67	    /**
68	     * Formats the owner's membership number as {@code '<customerCode>-M<YY>'}: the customer
69	     * code, the literal {@code '-M'}, and the last two digits of the registrationDate year.
70	     * Returns {@code null} unless both the customer code and registration date are present.
71	     */
72	    default String membershipNumber(Owner owner) {
73	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
74	            return null;
75	        }
76	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
77	        return owner.getCustomerCode() + "-M" + yy;
78	    }
79	
80	    /**
81	     * Returns the owner's numeric membership level. Starts at {@code 1}; adds {@code 1} when an
82	     * email address is present; adds {@code 1} when the owner has no namesakes (namesakeCount is
83	     * 0); capped at {@code 3} (level 4 is reserved for tenure).
84	     */
85	    default Integer membershipLevel(Owner owner) {
86	        if (owner == null) {
87	            return null;
88	        }
89	        int level = 1;
90	        String email = owner.getEmail();
91	        if (email != null && !email.isEmpty()) {
92	            level++;
93	        }
94	        Integer namesakeCount = owner.getNamesakeCount();
95	        if (namesakeCount != null && namesakeCount == 0) {
96	            level++;
97	        }
98	        return Math.min(level, 3);
99	    }
100	
101	    /** Fixed city-to-region table used to derive an owner's locality. */
102	    Map<String, String> CITY_REGION = Map.of(
103	        "Sydney", "NSW",
104	        "Melbourne", "VIC",
105	        "Brisbane", "QLD");
106	
107	    /**
108	     * Derives the owner's locality (region) from the city using the fixed city-to-region
109	     * table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
110	     * Returns {@code "UNKNOWN"} when the city is {@code null} or not in the table.
111	     */
112	    default String locality(Owner owner) {
113	        if (owner == null) {
114	            return null;
115	        }
116	        String city = owner.getCity();
117	        return city == null ? "UNKNOWN" : CITY_REGION.getOrDefault(city, "UNKNOWN");
118	    }
119	
120	    /**
121	     * Whether the owner carries the bulk-signup warning (more than 80 owners already created
122	     * on its registration day at creation time). A {@code null} stored value is treated as
123	     * {@code false}, so the field is always present in the response.
124	     */
125	    default Boolean bulkSignupWarning(Owner owner) {
126	        if (owner == null) {
127	            return null;
128	        }
129	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
130	    }
131	
132	    /**
133	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email address is
134	     * present, otherwise {@code PHONE}.
135	     */
136	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
137	        if (owner == null) {
138	            return null;
139	        }
140	        String email = owner.getEmail();
141	        return (email != null && !email.isEmpty())
142	            ? OwnerDto.ContactPreferenceEnum.EMAIL
143	            : OwnerDto.ContactPreferenceEnum.PHONE;
144	    }
145	
146	    /**
147	     * Derives the owner's {@code identityKey}, the single value into which duplicate detection is
148	     * consolidated: {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
149	     */
150	    default String identityKey(Owner owner) {
151	        return IdentityKeyNormalizer.derive(owner);
152	    }
153	
154	    @Mapping(target = "id", ignore = true)
155	    @Mapping(target = "pets", ignore = true)
156	    Owner toOwner(OwnerFieldsDto ownerDto);
157	
158	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
159	
160	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
161	
162	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
163	        OwnerPageDto ownerPageDto = new OwnerPageDto();
164	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
165	        ownerPageDto.setPage(ownerPage.getNumber());
166	        ownerPageDto.setSize(ownerPage.getSize());
167	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
168	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
169	        return ownerPageDto;
170	    }
171	}
