267	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
268	        if (bindingResult.hasErrors()) {
269	            errors.addAllErrors(bindingResult);
270	            List<String> errorFields = bindingResult.getFieldErrors().stream()
271	                .map(fieldError -> fieldError.getField())
272	                .distinct()
273	                .toList();
274	            detail.setProperty("errors", errorFields);
275	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
276	                .map(fieldError -> {
277	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
278	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
279	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
280	                        fieldError.getField(),
281	                        defaultMessage,
282	                        rejectedValue);
283	                    return new ValidationMessageDto(message)
284	                        .putAdditionalProperty("field", fieldError.getField())
285	                        .putAdditionalProperty("rejectedValue", rejectedValue)
286	                        .putAdditionalProperty("defaultMessage", defaultMessage);
287	                })
288	                .toList();
289	            logger.debug("Validation error at {} {}: {}",
290	                request.getMethod(),
291	                request.getRequestURI(),
292	                bindingResult.getFieldErrors());
293	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
294	            return ResponseEntity.status(status).body(detail);
295	        }
296	        return ResponseEntity.status(status).body(detail);
